-- SEEDERS FOR DOCUMENTATIONS

SELECT 
  'biofloc_thematic' as program_type,
  id as program_id,
  'seed-group-' || id as group_id,
  'after' as type,
  'documentations/biofloc-thematic/bioflok_thematic_2.webp' as path,
  'bioflok_thematic_2.webp' as file_name
FROM biofloc_thematic_programs
WHERE fiscal_year = 2025;

SELECT 
  'biofloc_thematic' as program_type,
  id as program_id,
  'seed-group-' || id as group_id,
  'before' as type,
  'documentations/biofloc-thematic/bioflok_thematic_1.webp' as path,
  'bioflok_thematic_1.webp' as file_name
FROM biofloc_thematic_programs
WHERE fiscal_year = 2025;

SELECT setval(pg_get_serial_sequence('kdmp_entities', 'id'), COALESCE(MAX(id), 0) + 1, false) FROM kdmp_entities;
SELECT setval(pg_get_serial_sequence('available_locations', 'id'), COALESCE(MAX(id), 0) + 1, false) FROM available_locations;
